package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.view.*;import org.json.*;

/** Reference layout and real two-pointer gesture in the Android WebView. */
public final class ChatPresentationTest extends DocumentEditorTest {
 String previous="",temporary="";
 float webScale(){final float[] value={0};runOnMainSync(()->value[0]=h.web.getScale());return value[0];}
 void fits(String stage)throws Exception{
  check(h.js("document.documentElement.scrollWidth<=innerWidth+1&&document.querySelector('.composer').scrollWidth<=document.querySelector('.composer').clientWidth+1").equals("true"),stage+": conversation and composer fit the viewport");
  check(h.js("[...document.querySelectorAll('.chat-followups button,.composer button')].every(b=>b.getBoundingClientRect().height>=43)").equals("true"),stage+": suggestions and composer remain touchable");
 }
 void event(long start,int action,float left,float right,float y,int count){MotionEvent.PointerProperties[] pp=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] pc=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){pp[i]=new MotionEvent.PointerProperties();pp[i].id=i;pp[i].toolType=MotionEvent.TOOL_TYPE_FINGER;pc[i]=new MotionEvent.PointerCoords();pc[i].x=i==0?left:right;pc[i].y=y;pc[i].pressure=1;pc[i].size=1;}MotionEvent ev=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,count,pp,pc,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);h.web.dispatchTouchEvent(ev);ev.recycle();}
 void pinch()throws Exception{final long t=SystemClock.uptimeMillis();final float center=h.web.getWidth()/2f,y=h.web.getHeight()*.35f;runOnMainSync(()->{event(t,MotionEvent.ACTION_DOWN,center-55,center+55,y,1);event(t,MotionEvent.ACTION_POINTER_DOWN+(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),center-55,center+55,y,2);});for(int i=1;i<=8;i++){final int step=i;Thread.sleep(25);runOnMainSync(()->event(t,MotionEvent.ACTION_MOVE,center-55-step*20,center+55+step*20,y,2));}runOnMainSync(()->{event(t,MotionEvent.ACTION_POINTER_UP+(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),center-215,center+215,y,2);event(t,MotionEvent.ACTION_UP,center-215,center+215,y,1);});Thread.sleep(500);}
 void checks()throws Exception{
  h=new MainHost(this);h.open();previous=((JSONObject)h.call("init",new JSONObject())).getJSONObject("chatSession").getString("id");temporary=((JSONObject)h.call("newChat",new JSONObject())).getJSONObject("session").getString("id");
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",new JSONObject().put("id","custom").put("label","Synthetic reference UI").put("baseUrl","https://127.0.0.1:9/v1").put("model","synthetic").put("protocol","chat").put("effort","off").put("apiKey","synthetic-not-a-real-key"))));
  h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","qa-sigma-user").put("sessionId",temporary).put("role","user").put("text","帮我整理今天的学习要点，并想想如何用于实际工作。").put("createdAt",System.currentTimeMillis()-1000)));
  h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","qa-sigma-answer").put("sessionId",temporary).put("role","assistant").put("text","## 先保留原文，再验证方法\n\n学习记录是原始材料，整理后的知识需要能追溯回具体的记录。\n\n- 明确每个要点在什么条件下适用。\n- 用一次实际工作检验方法是否有效。\n\n不要只看投入了多少时间，也要检查形成了哪些可以复用的方法。").put("followUps",new JSONArray().put("这些学习要点怎样用于工作？").put("帮我制定一个验证方法的小实验")).put("createdAt",System.currentTimeMillis())));
  h.js("window.__reload=true;location.reload()");until("window.__reload===undefined&&!!document.querySelector('.today-workspace')");h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{};window.__requests=0;window.__reply=null;window.__base=LifeNative;LifeNative={call:(a,p,id)=>{if(a==='ask'){const req=JSON.parse(p);if(req.automaticWiki){nativeReply({id,error:'Synthetic background paused'});return;}if(req.tool?.name==='plan_record_search'){nativeReply({id,data:{text:JSON.stringify({intent:'general',topic:'',keywords:[],dateStart:'',dateEnd:'',recordTypes:[]})}});return;}__requests++;__reply=()=>{nativeReply({id,data:{text:JSON.stringify({answer:'已收到追问，本次是本机合成回复。',records:[],citations:[],followUps:['如何验证这次学习的方法？','还能从哪些方面继续实践？']}),model:'synthetic'}});__reply=null;};}else __base.call(a,p,id);}}");click("[data-page=chat]");until("!!document.querySelector('[data-followup]')");
  check(h.js("getComputedStyle(document.querySelector('.chat-message:not(.user)')).backgroundColor==='rgba(0, 0, 0, 0)'&&!!document.querySelector('.assistant-mark')&&!!document.querySelector('.chat-turn-time time')").equals("true"),"Assistant has an open reading surface with identity and turn time: "+h.js("JSON.stringify({background:getComputedStyle(document.querySelector('.chat-message:not(.user)')).backgroundColor,mark:!!document.querySelector('.assistant-mark'),time:!!document.querySelector('.chat-turn-time time'),user:document.querySelector('.chat-message.user').outerHTML})"));
  check(h.js("document.querySelector('.composer').getBoundingClientRect().height<100").equals("true"),"Empty composer is a compact single row");fits("Portrait");Thread.sleep(400);h.js("ChatUI.bottom()");Thread.sleep(200);check(h.js("(()=>{const last=[...document.querySelectorAll('[data-followup]')].pop().getBoundingClientRect(),box=document.querySelector('#chat-scroll').getBoundingClientRect(),composer=document.querySelector('.composer').getBoundingClientRect();return last.bottom<=box.bottom+1&&last.bottom<=composer.top+1;})()").equals("true"),"Latest suggestion is fully visible above the composer at the end of the conversation");h.screenshot("chat-reference-layout.png");
  int height=Integer.parseInt(h.js("innerHeight"));h.js("window.__input=document.querySelector('#chat-input');__input.value='还没发送的个人草稿';__input.dispatchEvent(new Event('input'));__input.setSelectionRange(2,4)");h.tap("[data-followup]",false);until("!!__reply");
  check(h.js("__requests===1&&document.querySelectorAll('.chat-message.user').length===2&&Array.from(document.querySelectorAll('.chat-message.user')).slice(-1)[0].textContent.includes('这些学习要点怎样用于工作？')").equals("true"),"A suggestion immediately sends one real-path user message and model request");
  check(h.js("document.querySelector('#chat-input')===__input&&__input.value==='还没发送的个人草稿'&&__input.selectionStart===2&&__input.selectionEnd===4").equals("true"),"Suggestion submission preserves the original draft, selection and textarea");check(Integer.parseInt(h.js("innerHeight"))==height,"Suggestion does not summon the Android keyboard");h.screenshot("chat-reference-loading.png");
  h.js("__reply()");until("document.body.innerText.includes('已收到追问，本次是本机合成回复。')&&!!document.querySelector('[data-followup]')");check(h.js("__requests===1&&__input.value==='还没发送的个人草稿'").equals("true"),"Finishing the reply does not overwrite the restored draft");h.tap("#chat-input",false);until("innerHeight<"+(height-100));h.screenshot("chat-reference-keyboard.png");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(300);
  final boolean[] noZoom={false};runOnMainSync(()->noZoom[0]=!h.web.getSettings().supportZoom()&&!h.web.getSettings().getBuiltInZoomControls()&&!h.web.getSettings().getDisplayZoomControls());check(noZoom[0],"Browser-level pinch and zoom controls are disabled");
  float scale=webScale();String width=h.js("innerWidth");pinch();check(Math.abs(webScale()-scale)<.001&&h.js("innerWidth").equals(width),"Real two-finger gesture cannot resize the ordinary chat UI");
  runOnMainSync(()->h.web.getSettings().setTextZoom(200));Thread.sleep(300);fits("200 percent text");h.screenshot("chat-reference-large.png");runOnMainSync(()->h.web.getSettings().setTextZoom(100));
 }
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;String settings=getTargetContext().getSharedPreferences("secure",0).getString("settings",null);try{if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Disposable emulator required");checks();ok=true;out.putString("stream","PASS ChatPresentationTest: "+passed+" checks\n");}catch(Throwable error){out.putString("stream","FAIL ChatPresentationTest after "+passed+": "+android.util.Log.getStackTraceString(error));try{h.screenshot("chat-reference-failure.png");}catch(Exception ignored){}}finally{try{if(h!=null){runOnMainSync(()->h.web.getSettings().setTextZoom(100));if(!temporary.isEmpty())h.call("deleteChat",new JSONObject().put("sessionId",temporary));if(!previous.isEmpty())h.call("getChat",new JSONObject().put("sessionId",previous));runOnMainSync(()->h.activity.finish());}}catch(Exception ignored){}android.content.SharedPreferences.Editor e=getTargetContext().getSharedPreferences("secure",0).edit();if(settings==null)e.remove("settings");else e.putString("settings",settings);e.commit();}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
